'use client';
import {useCallback,useEffect,useState} from 'react';
import {apiFetch} from '@/lib/api-client';
import styles from './AdminEmailDeliveries.module.css';
import {useDataRefresh} from '@/lib/data-refresh';

type Delivery={id:string;eventType:string;recipientEmail:string;propertyId?:string;createdAt?:string;status:string;retryCount:number;errorSummary?:string;providerStatus?:number;providerErrorCode?:string};

export default function AdminEmailDeliveries(){
  const [rows,setRows]=useState<Delivery[]>([]),[status,setStatus]=useState(''),[eventType,setEventType]=useState(''),[date,setDate]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState(''),[retrying,setRetrying]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const query=new URLSearchParams();if(status)query.set('status',status);if(eventType)query.set('eventType',eventType);const response=await apiFetch(`/api/admin/email-deliveries?${query}`);if(!response.ok)throw new Error();const data=await response.json();setRows(Array.isArray(data.deliveries)?data.deliveries:[]);}catch{setError('Email delivery history could not be loaded.');}finally{setLoading(false);}},[status,eventType]);
  useEffect(()=>{void load();},[load]);
  useDataRefresh(['emails'],()=>{void load();});
  const retry=async(id:string)=>{setRetrying(id);setError('');try{const response=await apiFetch(`/api/admin/email-deliveries/${encodeURIComponent(id)}/retry`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error();await load();}catch{setError('This delivery could not be queued for retry.');}finally{setRetrying('');}};
  const visible=date?rows.filter(row=>String(row.createdAt||'').slice(0,10)===date):rows;
  return <section aria-labelledby="email-delivery-heading"><h2 id="email-delivery-heading" className="text-2xl font-semibold mb-2">Email deliveries</h2><p className="text-muted-foreground mb-4">Review transactional events and retry eligible pending or failed deliveries without changing recipients or content. Sent means provider acceptance; inbox delivery is not confirmed here.</p><div className={styles.toolbar}><button type="button" disabled={loading} onClick={()=>void load()}>Refresh</button><select aria-label="Delivery status" value={status} onChange={event=>setStatus(event.target.value)}><option value="">All statuses</option><option value="pending">Pending</option><option value="sent">Sent</option><option value="failed">Failed</option><option value="sending">Sending</option><option value="suppressed">Suppressed</option><option value="cancelled">Cancelled</option></select><input aria-label="Event type" placeholder="Filter event type" value={eventType} onChange={event=>setEventType(event.target.value)}/><input aria-label="Created date" type="date" value={date} onChange={event=>setDate(event.target.value)}/></div>{error&&<p role="alert" className={styles.message}>{error}</p>}{loading?<p className={styles.message}>Loading delivery history…</p>:<div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>Event</th><th>Recipient</th><th>Property</th><th>Created</th><th>Status</th><th>Failure</th><th>Action</th></tr></thead><tbody>{visible.map(row=><tr key={row.id}><td>{row.eventType}</td><td>{row.recipientEmail}</td><td>{row.propertyId||'—'}</td><td>{row.createdAt?new Date(row.createdAt).toLocaleString():'—'}</td><td className={styles.status}>{row.status}</td><td>{row.providerStatus&&<small>HTTP {row.providerStatus}{row.providerErrorCode?' / '+row.providerErrorCode:''}</small>} {row.errorSummary||'—'}</td><td><button className={styles.retry} disabled={!['pending','failed'].includes(row.status)||row.retryCount>=5||retrying===row.id} onClick={()=>void retry(row.id)}>{retrying===row.id?'Queuing…':'Retry'}</button></td></tr>)}{!visible.length&&<tr><td colSpan={7}>No matching delivery records.</td></tr>}</tbody></table></div>}</section>;
}
